  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nenum Rank {\n  NONE\n  ONE_STAR\n  TWO_STAR\n  THREE_STAR\n}\n\nenum IncomeType {\n  DIRECT_20\n  MATRIX_40\n  LEVEL_10\n  CAPITAL_GAIN_20\n  RANK_10\n  MAGICAL\n}\n\nenum TxType {\n  WITHDRAWAL\n  P2P_TRANSFER\n  PACKAGE_UPGRADE\n  CAPITAL_GAIN_JOIN\n}\n\nenum TxStatus {\n  PENDING\n  COMPLETED\n  REJECTED\n}\n\n// --------------------------------------------------------------------------\n// 1. User & Sponsor Hierarchy\n// --------------------------------------------------------------------------\nmodel User {\n  id              Int    @id @default(autoincrement())\n  walletAddress   String @unique\n  sponsorId       Int?\n  sponsor         User?  @relation(\"SponsorshipTree\", fields: [sponsorId], references: [id])\n  directReferrals User[] @relation(\"SponsorshipTree\")\n\n  currentPackage Int  @default(0) // $10, $20, $40, $80, $160, $320, $640, $1280\n  rank           Rank @default(NONE)\n\n  // 500% Capping Rules\n  cappingLimit  Decimal @default(0.00) @db.Decimal(18, 4) // currentPackage * 5\n  cappingEarned Decimal @default(0.00) @db.Decimal(18, 4) // tracked until 500% cap\n\n  // Total Lifetime Earnings Breakdown\n  totalEarned        Decimal @default(0.00) @db.Decimal(18, 4)\n  totalDirectEarned  Decimal @default(0.00) @db.Decimal(18, 4)\n  totalMatrixEarned  Decimal @default(0.00) @db.Decimal(18, 4)\n  totalLevelEarned   Decimal @default(0.00) @db.Decimal(18, 4)\n  totalCapitalEarned Decimal @default(0.00) @db.Decimal(18, 4)\n  totalRankEarned    Decimal @default(0.00) @db.Decimal(18, 4)\n  totalMagicalEarned Decimal @default(0.00) @db.Decimal(18, 4)\n\n  // Fast Cached Metrics\n  directsCount Int      @default(0)\n  teamSize     Int      @default(0)\n  isActive     Boolean  @default(true)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Relations\n  packages          PackageActivation[]\n  matrixPositions   MatrixPosition[]\n  earningsReceived  EarningLog[]              @relation(\"ReceivedEarnings\")\n  earningsGenerated EarningLog[]              @relation(\"GeneratedEarnings\")\n  capitalGainPlans  CapitalGainSubscription[]\n  transactions      Transaction[]\n\n  @@index([walletAddress])\n  @@index([sponsorId])\n}\n\n// --------------------------------------------------------------------------\n// 2. Package Activations ($10, $20, $40, $80, $160, $320, $640, $1280)\n// --------------------------------------------------------------------------\nmodel PackageActivation {\n  id            Int      @id @default(autoincrement())\n  userId        Int\n  user          User     @relation(fields: [userId], references: [id])\n  packageAmount Int // 10, 20, 40, 80, etc.\n  txHash        String   @unique\n  blockNumber   BigInt?\n  createdAt     DateTime @default(now())\n\n  @@index([userId, packageAmount])\n}\n\n// --------------------------------------------------------------------------\n// 3. 40% Global Matrix Positions & 2-Slot Recycling\n// --------------------------------------------------------------------------\nmodel MatrixPosition {\n  id            Int  @id @default(autoincrement())\n  userId        Int\n  user          User @relation(fields: [userId], references: [id])\n  packageAmount Int // $10, $20, $40, $80...\n  cycleNumber   Int  @default(1)\n\n  // Slot 1: Re-entry ($4 on $10)\n  slot1Filled   Boolean   @default(false)\n  slot1UserId   Int?\n  slot1FilledAt DateTime?\n\n  // Slot 2: Instant Withdrawal ($4 on $10)\n  slot2Filled   Boolean   @default(false)\n  slot2UserId   Int?\n  slot2FilledAt DateTime?\n\n  isCompleted  Boolean  @default(false)\n  reEntryCount Int      @default(0)\n  totalEarned  Decimal  @default(0.00) @db.Decimal(18, 4)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([userId, packageAmount, isCompleted])\n}\n\n// --------------------------------------------------------------------------\n// 4. 10-Level Lineage & Genealogy Tree (1% per level x 10)\n// --------------------------------------------------------------------------\nmodel LevelTree {\n  id           Int      @id @default(autoincrement())\n  ancestorId   Int // Upline\n  descendantId Int // Downline member\n  depth        Int // 1 to 10\n  createdAt    DateTime @default(now())\n\n  @@unique([ancestorId, descendantId])\n  @@index([ancestorId, depth])\n  @@index([descendantId])\n}\n\n// --------------------------------------------------------------------------\n// 5. 20% Capital Gain Passive Plan ($150 -> $300, $4 every 10 days)\n// --------------------------------------------------------------------------\nmodel CapitalGainSubscription {\n  id                Int       @id @default(autoincrement())\n  userId            Int\n  user              User      @relation(fields: [userId], references: [id])\n  packageAmount     Decimal   @default(150.00) @db.Decimal(10, 2)\n  payoutPerCycle    Decimal   @default(4.00) @db.Decimal(10, 2)\n  totalReturnTarget Decimal   @default(300.00) @db.Decimal(10, 2)\n  totalPaid         Decimal   @default(0.00) @db.Decimal(10, 2)\n  cyclesCompleted   Int       @default(0) // Max 75 cycles (75 * $4 = $300)\n  maxCycles         Int       @default(75)\n  lastPayoutAt      DateTime?\n  nextPayoutAt      DateTime\n  isActive          Boolean   @default(true)\n  createdAt         DateTime  @default(now())\n\n  @@index([userId, isActive])\n  @@index([nextPayoutAt, isActive])\n}\n\n// --------------------------------------------------------------------------\n// 6. 100% Distribution Earnings Audit Logs\n// --------------------------------------------------------------------------\nmodel EarningLog {\n  id         Int   @id @default(autoincrement())\n  userId     Int // Recipient of commission\n  user       User  @relation(\"ReceivedEarnings\", fields: [userId], references: [id])\n  fromUserId Int? // Member who activated package\n  fromUser   User? @relation(\"GeneratedEarnings\", fields: [fromUserId], references: [id])\n\n  incomeType    IncomeType // DIRECT_20, MATRIX_40, LEVEL_10, CAPITAL_GAIN_20, RANK_10, MAGICAL\n  amount        Decimal    @db.Decimal(18, 4)\n  level         Int? // 1 to 10 (for LEVEL_10)\n  packageAmount Int?\n  txHash        String?\n  createdAt     DateTime   @default(now())\n\n  @@index([userId, incomeType])\n  @@index([createdAt])\n}\n\n// --------------------------------------------------------------------------\n// 7. Withdrawals & P2P Transfers (10% & 5% Deductions)\n// --------------------------------------------------------------------------\nmodel Transaction {\n  id                  Int      @id @default(autoincrement())\n  userId              Int\n  user                User     @relation(fields: [userId], references: [id])\n  type                TxType // WITHDRAWAL, P2P_TRANSFER, etc.\n  grossAmount         Decimal  @db.Decimal(18, 4)\n  deductionRate       Decimal  @db.Decimal(5, 2) // 10.00% or 5.00%\n  deductionAmount     Decimal  @db.Decimal(18, 4)\n  netAmount           Decimal  @db.Decimal(18, 4)\n  recipientWalletOrId String?\n  txHash              String?\n  status              TxStatus @default(COMPLETED)\n  createdAt           DateTime @default(now())\n\n  @@index([userId, type])\n}\n",
